CREATE TABLE IF NOT EXISTS "drugs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- NDC, dm+d or equivalent product identifier. One code per strength and form, which is why a single trade name produces several rows.
	"product_code" VARCHAR(24) NOT NULL UNIQUE,
	-- Trade or label name as printed.
	"name" VARCHAR(200) NOT NULL,
	-- Active ingredient. Generic substitution and duplicate-therapy checks both key on this rather than the trade name.
	"generic_name" VARCHAR(200) NOT NULL,
	-- Strength per unit, e.g. 500 mg. Kept as text because combination products carry several.
	"strength" VARCHAR(60) NOT NULL,
	-- tablet | capsule | solution | cream | inhaler | injection. Together with strength this is what makes a product distinct.
	"form" VARCHAR(40) NOT NULL,
	-- Units per manufacturer pack. Null for products dispensed loose by count.
	"pack_size" INTEGER,
	-- II to V where applicable, null otherwise. Non-null forces a register entry on every dispense.
	"controlled_schedule" VARCHAR(8),
	-- Forces a counselling record before the sale can close, for drugs whose risk is in how they are used.
	"requires_counselling" BOOLEAN NOT NULL DEFAULT false,
	-- False for discontinued lines. Never deleted, because batches and dispense history still point here.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drugs" IS 'The product catalogue, one row per distinct strength and form. Everything clinical — interactions, allergies, duplicate therapy — matches on the generic name, so it is a first-class column rather than something parsed out of the label.';
COMMENT ON COLUMN "drugs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drugs"."product_code" IS 'NDC, dm+d or equivalent product identifier. One code per strength and form, which is why a single trade name produces several rows.';
COMMENT ON COLUMN "drugs"."name" IS 'Trade or label name as printed.';
COMMENT ON COLUMN "drugs"."generic_name" IS 'Active ingredient. Generic substitution and duplicate-therapy checks both key on this rather than the trade name.';
COMMENT ON COLUMN "drugs"."strength" IS 'Strength per unit, e.g. 500 mg. Kept as text because combination products carry several.';
COMMENT ON COLUMN "drugs"."form" IS 'tablet | capsule | solution | cream | inhaler | injection. Together with strength this is what makes a product distinct.';
COMMENT ON COLUMN "drugs"."pack_size" IS 'Units per manufacturer pack. Null for products dispensed loose by count.';
COMMENT ON COLUMN "drugs"."controlled_schedule" IS 'II to V where applicable, null otherwise. Non-null forces a register entry on every dispense.';
COMMENT ON COLUMN "drugs"."requires_counselling" IS 'Forces a counselling record before the sale can close, for drugs whose risk is in how they are used.';
COMMENT ON COLUMN "drugs"."is_active" IS 'False for discontinued lines. Never deleted, because batches and dispense history still point here.';

CREATE INDEX "idx_drugs_generic"
ON "drugs" ("generic_name");

CREATE TABLE IF NOT EXISTS "drug_batches" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Product this stock is of.
	"drug_id" BIGINT NOT NULL,
	-- Manufacturer lot. This is the value a recall names, so it has to be carried on the stock rather than reconstructed from invoices.
	"lot_number" VARCHAR(60) NOT NULL,
	-- Last day the batch may be dispensed. The sort key for first-expired-first-out picking.
	"expiry_date" DATE NOT NULL,
	-- Units booked in. Never changed, so shrinkage is computable as received minus dispensed minus wasted.
	"quantity_received" INTEGER NOT NULL,
	-- Units remaining. Decremented inside the dispense transaction, and constrained to stay at or above zero.
	"quantity_on_hand" INTEGER NOT NULL DEFAULT 0,
	-- Wholesaler the batch came from, for recall notification and credit notes.
	"supplier_name" VARCHAR(160),
	-- Acquisition cost per unit in minor units, used for margin and for write-off value when a batch expires.
	"unit_cost_cents" INTEGER,
	-- ISO 4217 currency of unit_cost_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Goods-in time.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- available | quarantined | recalled | expired | depleted. A recall flips a batch out of picking without touching its history.
	"status" VARCHAR(20) NOT NULL DEFAULT 'available',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drug_batches" IS 'Physical stock, one row per lot. Inventory lives here rather than as a count on the drug because expiry, recall and cost are all properties of a lot, and none of them survive being averaged into a single number.';
COMMENT ON COLUMN "drug_batches"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drug_batches"."drug_id" IS 'Product this stock is of.';
COMMENT ON COLUMN "drug_batches"."lot_number" IS 'Manufacturer lot. This is the value a recall names, so it has to be carried on the stock rather than reconstructed from invoices.';
COMMENT ON COLUMN "drug_batches"."expiry_date" IS 'Last day the batch may be dispensed. The sort key for first-expired-first-out picking.';
COMMENT ON COLUMN "drug_batches"."quantity_received" IS 'Units booked in. Never changed, so shrinkage is computable as received minus dispensed minus wasted.';
COMMENT ON COLUMN "drug_batches"."quantity_on_hand" IS 'Units remaining. Decremented inside the dispense transaction, and constrained to stay at or above zero.';
COMMENT ON COLUMN "drug_batches"."supplier_name" IS 'Wholesaler the batch came from, for recall notification and credit notes.';
COMMENT ON COLUMN "drug_batches"."unit_cost_cents" IS 'Acquisition cost per unit in minor units, used for margin and for write-off value when a batch expires.';
COMMENT ON COLUMN "drug_batches"."currency_code" IS 'ISO 4217 currency of unit_cost_cents.';
COMMENT ON COLUMN "drug_batches"."received_at" IS 'Goods-in time.';
COMMENT ON COLUMN "drug_batches"."status" IS 'available | quarantined | recalled | expired | depleted. A recall flips a batch out of picking without touching its history.';

CREATE UNIQUE INDEX "uq_batch_drug_lot"
ON "drug_batches" ("drug_id", "lot_number");
CREATE INDEX "idx_batch_fefo_pick"
ON "drug_batches" ("drug_id", "status", "expiry_date");

CREATE TABLE IF NOT EXISTS "patients" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- First name, matched against the prescription when handing over.
	"given_name" VARCHAR(100) NOT NULL,
	-- Surname.
	"family_name" VARCHAR(100) NOT NULL,
	-- Identity check at collection and the basis for paediatric and geriatric dose warnings.
	"date_of_birth" DATE NOT NULL,
	-- Used for the ready-to-collect message.
	"phone" VARCHAR(32),
	-- Delivery address, and the address a controlled-substance register entry must record.
	"address_line" VARCHAR(255),
	-- Language the label and counselling are produced in. Getting this wrong is a safety issue, not a courtesy one.
	"preferred_language" VARCHAR(16) NOT NULL DEFAULT 'en',
	-- First registration at this pharmacy.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "patients" IS 'The person the medicine is for, who is not always the person collecting it. Retained for the statutory record-keeping period rather than deleted on request.';
COMMENT ON COLUMN "patients"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "patients"."given_name" IS 'First name, matched against the prescription when handing over.';
COMMENT ON COLUMN "patients"."family_name" IS 'Surname.';
COMMENT ON COLUMN "patients"."date_of_birth" IS 'Identity check at collection and the basis for paediatric and geriatric dose warnings.';
COMMENT ON COLUMN "patients"."phone" IS 'Used for the ready-to-collect message.';
COMMENT ON COLUMN "patients"."address_line" IS 'Delivery address, and the address a controlled-substance register entry must record.';
COMMENT ON COLUMN "patients"."preferred_language" IS 'Language the label and counselling are produced in. Getting this wrong is a safety issue, not a courtesy one.';
COMMENT ON COLUMN "patients"."created_at" IS 'First registration at this pharmacy.';

CREATE INDEX "idx_patients_name_dob"
ON "patients" ("family_name", "date_of_birth");

CREATE TABLE IF NOT EXISTS "patient_allergies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient the allergy belongs to.
	"patient_id" BIGINT NOT NULL,
	-- Coded allergen where one exists, so the check can match structurally instead of by string.
	"allergen_code" VARCHAR(24),
	-- Readable substance name, which for class allergies such as penicillins is the only thing recorded.
	"allergen_name" VARCHAR(160) NOT NULL,
	-- What happened, e.g. urticaria or anaphylaxis.
	"reaction" VARCHAR(255),
	-- mild | moderate | severe | unknown. Severity decides whether a match is a warning or a hard stop.
	"severity" VARCHAR(16) NOT NULL DEFAULT 'unknown',
	-- When it was captured.
	"recorded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "patient_allergies" IS 'The allergy list read on every dispense. Deliberately small and directly keyed by patient, because it sits in the hot path of a check that must complete while the customer is at the counter.';
COMMENT ON COLUMN "patient_allergies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "patient_allergies"."patient_id" IS 'Patient the allergy belongs to.';
COMMENT ON COLUMN "patient_allergies"."allergen_code" IS 'Coded allergen where one exists, so the check can match structurally instead of by string.';
COMMENT ON COLUMN "patient_allergies"."allergen_name" IS 'Readable substance name, which for class allergies such as penicillins is the only thing recorded.';
COMMENT ON COLUMN "patient_allergies"."reaction" IS 'What happened, e.g. urticaria or anaphylaxis.';
COMMENT ON COLUMN "patient_allergies"."severity" IS 'mild | moderate | severe | unknown. Severity decides whether a match is a warning or a hard stop.';
COMMENT ON COLUMN "patient_allergies"."recorded_at" IS 'When it was captured.';

CREATE UNIQUE INDEX "uq_allergy_patient_allergen"
ON "patient_allergies" ("patient_id", "allergen_name");

CREATE TABLE IF NOT EXISTS "prescribers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Prescriber registration or DEA number. Controlled prescriptions are invalid without a verified one.
	"registration_number" VARCHAR(40) NOT NULL UNIQUE,
	-- Name as signed.
	"full_name" VARCHAR(160) NOT NULL,
	-- Surgery or clinic, used when querying an unclear prescription.
	"practice_name" VARCHAR(160),
	-- Called for clarification, which is a routine daily event.
	"phone" VARCHAR(32),
	-- Set once the registration is confirmed with the regulator.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "prescribers" IS 'Whoever signed the prescription. Kept as a table so an unclear or suspicious prescription can be traced, and so repeat prescribers are not re-keyed with slightly different spellings.';
COMMENT ON COLUMN "prescribers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "prescribers"."registration_number" IS 'Prescriber registration or DEA number. Controlled prescriptions are invalid without a verified one.';
COMMENT ON COLUMN "prescribers"."full_name" IS 'Name as signed.';
COMMENT ON COLUMN "prescribers"."practice_name" IS 'Surgery or clinic, used when querying an unclear prescription.';
COMMENT ON COLUMN "prescribers"."phone" IS 'Called for clarification, which is a routine daily event.';
COMMENT ON COLUMN "prescribers"."is_verified" IS 'Set once the registration is confirmed with the regulator.';

CREATE TABLE IF NOT EXISTS "prescriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient prescribed for.
	"patient_id" BIGINT NOT NULL,
	-- Signing prescriber.
	"prescriber_id" BIGINT NOT NULL,
	-- Product prescribed. One prescription row per drug keeps the refill counter unambiguous.
	"drug_id" BIGINT NOT NULL,
	-- Token or barcode from the e-prescribing network. Null for paper scripts.
	"external_reference" VARCHAR(64),
	-- Date signed. Legal validity is counted from here, not from receipt.
	"written_on" DATE NOT NULL,
	-- Last day it may be dispensed. Controlled scripts expire far sooner than repeats.
	"expires_on" DATE,
	-- The sig, as it will be printed on the label.
	"directions" VARCHAR(255) NOT NULL,
	-- Units per fill.
	"quantity_authorised" INTEGER NOT NULL,
	-- Intended duration of one fill, used for refill-too-soon checks.
	"days_supply" INTEGER,
	-- Repeats the prescriber allowed beyond the first fill.
	"refills_authorised" INTEGER NOT NULL DEFAULT 0,
	-- Decremented on each dispense. Kept as a column rather than counted from dispense history so the counter can be adjusted for a transferred or partially filled script.
	"refills_remaining" INTEGER NOT NULL DEFAULT 0,
	-- received | ready | partially_filled | completed | expired | cancelled | transferred_out.
	"status" VARCHAR(24) NOT NULL DEFAULT 'received',
	-- When the pharmacy took it in.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "prescriptions" IS 'An authorisation to dispense, which is not itself a dispense. One prescription produces many dispense rows over its life, and it is the difference between the two that makes refills, partial fills and owings tractable.';
COMMENT ON COLUMN "prescriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "prescriptions"."patient_id" IS 'Patient prescribed for.';
COMMENT ON COLUMN "prescriptions"."prescriber_id" IS 'Signing prescriber.';
COMMENT ON COLUMN "prescriptions"."drug_id" IS 'Product prescribed. One prescription row per drug keeps the refill counter unambiguous.';
COMMENT ON COLUMN "prescriptions"."external_reference" IS 'Token or barcode from the e-prescribing network. Null for paper scripts.';
COMMENT ON COLUMN "prescriptions"."written_on" IS 'Date signed. Legal validity is counted from here, not from receipt.';
COMMENT ON COLUMN "prescriptions"."expires_on" IS 'Last day it may be dispensed. Controlled scripts expire far sooner than repeats.';
COMMENT ON COLUMN "prescriptions"."directions" IS 'The sig, as it will be printed on the label.';
COMMENT ON COLUMN "prescriptions"."quantity_authorised" IS 'Units per fill.';
COMMENT ON COLUMN "prescriptions"."days_supply" IS 'Intended duration of one fill, used for refill-too-soon checks.';
COMMENT ON COLUMN "prescriptions"."refills_authorised" IS 'Repeats the prescriber allowed beyond the first fill.';
COMMENT ON COLUMN "prescriptions"."refills_remaining" IS 'Decremented on each dispense. Kept as a column rather than counted from dispense history so the counter can be adjusted for a transferred or partially filled script.';
COMMENT ON COLUMN "prescriptions"."status" IS 'received | ready | partially_filled | completed | expired | cancelled | transferred_out.';
COMMENT ON COLUMN "prescriptions"."received_at" IS 'When the pharmacy took it in.';

CREATE INDEX "idx_prescriptions_patient_status"
ON "prescriptions" ("patient_id", "status");
CREATE INDEX "idx_prescriptions_queue"
ON "prescriptions" ("status", "received_at");

CREATE TABLE IF NOT EXISTS "pharmacists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Professional registration. Every dispense is attributable to one.
	"licence_number" VARCHAR(40) NOT NULL UNIQUE,
	-- Name recorded against the dispense and the register.
	"full_name" VARCHAR(160) NOT NULL,
	-- pharmacist | technician | intern. Only a pharmacist may sign off a controlled dispense or a clinical override.
	"role" VARCHAR(24) NOT NULL DEFAULT 'pharmacist',
	-- False after departure. Historic dispenses stay attributed to them.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pharmacists" IS 'Staff who can be named on a record. Deactivated rather than deleted, because the register has to name a real, identifiable person for as long as it is retained.';
COMMENT ON COLUMN "pharmacists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pharmacists"."licence_number" IS 'Professional registration. Every dispense is attributable to one.';
COMMENT ON COLUMN "pharmacists"."full_name" IS 'Name recorded against the dispense and the register.';
COMMENT ON COLUMN "pharmacists"."role" IS 'pharmacist | technician | intern. Only a pharmacist may sign off a controlled dispense or a clinical override.';
COMMENT ON COLUMN "pharmacists"."is_active" IS 'False after departure. Historic dispenses stay attributed to them.';

CREATE TABLE IF NOT EXISTS "dispenses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Authorisation being filled.
	"prescription_id" BIGINT NOT NULL,
	-- The exact lot the units came out of. This single column is what makes a recall answerable: every patient who received the lot is one join away.
	"batch_id" BIGINT NOT NULL,
	-- Patient supplied. Denormalised from the prescription because recall and history queries start here.
	"patient_id" BIGINT NOT NULL,
	-- Who performed the final check. Never null — an unattributed dispense is a regulatory finding.
	"pharmacist_id" BIGINT NOT NULL,
	-- Which fill of the prescription this is, starting at 1. Makes the refill sequence explicit rather than inferred from timestamps.
	"fill_number" INTEGER NOT NULL DEFAULT 1,
	-- Units handed over. May be less than authorised when stock is short, which is what a partial fill is.
	"quantity_dispensed" INTEGER NOT NULL,
	-- True when the balance is still owed, so the owing report is a filter rather than a calculation.
	"is_partial" BOOLEAN NOT NULL DEFAULT false,
	-- Directions as printed on this label, snapshotted because a later prescription edit must not rewrite what the patient was told.
	"label_directions" VARCHAR(255) NOT NULL,
	-- Total charged to the patient in minor units, after any insurance contribution.
	"price_cents" INTEGER NOT NULL DEFAULT 0,
	-- ISO 4217 currency of price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Handover time. Drives refill-too-soon logic on the next fill.
	"dispensed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dispenses" IS 'The event that moves stock and supplies a patient. It decrements exactly one batch in the same transaction, which is why quantity on hand and the recall trail can never disagree.';
COMMENT ON COLUMN "dispenses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dispenses"."prescription_id" IS 'Authorisation being filled.';
COMMENT ON COLUMN "dispenses"."batch_id" IS 'The exact lot the units came out of. This single column is what makes a recall answerable: every patient who received the lot is one join away.';
COMMENT ON COLUMN "dispenses"."patient_id" IS 'Patient supplied. Denormalised from the prescription because recall and history queries start here.';
COMMENT ON COLUMN "dispenses"."pharmacist_id" IS 'Who performed the final check. Never null — an unattributed dispense is a regulatory finding.';
COMMENT ON COLUMN "dispenses"."fill_number" IS 'Which fill of the prescription this is, starting at 1. Makes the refill sequence explicit rather than inferred from timestamps.';
COMMENT ON COLUMN "dispenses"."quantity_dispensed" IS 'Units handed over. May be less than authorised when stock is short, which is what a partial fill is.';
COMMENT ON COLUMN "dispenses"."is_partial" IS 'True when the balance is still owed, so the owing report is a filter rather than a calculation.';
COMMENT ON COLUMN "dispenses"."label_directions" IS 'Directions as printed on this label, snapshotted because a later prescription edit must not rewrite what the patient was told.';
COMMENT ON COLUMN "dispenses"."price_cents" IS 'Total charged to the patient in minor units, after any insurance contribution.';
COMMENT ON COLUMN "dispenses"."currency_code" IS 'ISO 4217 currency of price_cents.';
COMMENT ON COLUMN "dispenses"."dispensed_at" IS 'Handover time. Drives refill-too-soon logic on the next fill.';

CREATE UNIQUE INDEX "uq_dispense_prescription_fill"
ON "dispenses" ("prescription_id", "fill_number");
CREATE INDEX "idx_dispense_batch"
ON "dispenses" ("batch_id");
CREATE INDEX "idx_dispense_patient_time"
ON "dispenses" ("patient_id", "dispensed_at");

CREATE TABLE IF NOT EXISTS "drug_interactions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- One side of the pair. Stored twice, once per direction, so a check is a single indexed lookup.
	"drug_id" BIGINT NOT NULL,
	-- The other side of the pair.
	"interacts_with_drug_id" BIGINT NOT NULL,
	-- minor | moderate | major | contraindicated. Only the top two stop a sale.
	"severity" VARCHAR(16) NOT NULL,
	-- Why they interact, e.g. CYP3A4 inhibition.
	"mechanism" VARCHAR(255),
	-- What the pharmacist should do about it, shown verbatim in the warning.
	"guidance" VARCHAR(500),
	-- Reference database the pair came from, so a disputed warning can be traced.
	"source" VARCHAR(80),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drug_interactions" IS 'Reference data for the interaction check. Pairs are stored in both directions on purpose: halving the rows would double the query, and this lookup runs several times per sale.';
COMMENT ON COLUMN "drug_interactions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drug_interactions"."drug_id" IS 'One side of the pair. Stored twice, once per direction, so a check is a single indexed lookup.';
COMMENT ON COLUMN "drug_interactions"."interacts_with_drug_id" IS 'The other side of the pair.';
COMMENT ON COLUMN "drug_interactions"."severity" IS 'minor | moderate | major | contraindicated. Only the top two stop a sale.';
COMMENT ON COLUMN "drug_interactions"."mechanism" IS 'Why they interact, e.g. CYP3A4 inhibition.';
COMMENT ON COLUMN "drug_interactions"."guidance" IS 'What the pharmacist should do about it, shown verbatim in the warning.';
COMMENT ON COLUMN "drug_interactions"."source" IS 'Reference database the pair came from, so a disputed warning can be traced.';

CREATE UNIQUE INDEX "uq_interaction_pair"
ON "drug_interactions" ("drug_id", "interacts_with_drug_id");

CREATE TABLE IF NOT EXISTS "safety_checks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Dispense the check was run for. Checks are recorded against the fill, not the prescription, because stock and history differ per fill.
	"dispense_id" BIGINT NOT NULL,
	-- interaction | allergy | duplicate_therapy | dose_range | refill_too_soon.
	"check_type" VARCHAR(24) NOT NULL,
	-- minor | moderate | major | contraindicated, copied from the rule that fired.
	"severity" VARCHAR(16) NOT NULL,
	-- The other drug involved, for interaction and duplicate-therapy hits.
	"conflicting_drug_id" BIGINT,
	-- The allergy record that matched, for allergy hits.
	"allergy_id" BIGINT,
	-- cleared | overridden | blocked. A blocked check means no dispense row was ever written.
	"outcome" VARCHAR(20) NOT NULL,
	-- Why the pharmacist proceeded anyway. Required by policy whenever outcome is overridden, and the field a coroner reads first.
	"override_reason" VARCHAR(255),
	-- Pharmacist who resolved the warning.
	"checked_by_id" BIGINT,
	-- When the check ran.
	"checked_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "safety_checks" IS 'The audit trail of clinical screening. Cleared checks are stored as well as overridden ones, because proving that a check ran and found nothing is exactly as important as recording that one was ignored.';
COMMENT ON COLUMN "safety_checks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "safety_checks"."dispense_id" IS 'Dispense the check was run for. Checks are recorded against the fill, not the prescription, because stock and history differ per fill.';
COMMENT ON COLUMN "safety_checks"."check_type" IS 'interaction | allergy | duplicate_therapy | dose_range | refill_too_soon.';
COMMENT ON COLUMN "safety_checks"."severity" IS 'minor | moderate | major | contraindicated, copied from the rule that fired.';
COMMENT ON COLUMN "safety_checks"."conflicting_drug_id" IS 'The other drug involved, for interaction and duplicate-therapy hits.';
COMMENT ON COLUMN "safety_checks"."allergy_id" IS 'The allergy record that matched, for allergy hits.';
COMMENT ON COLUMN "safety_checks"."outcome" IS 'cleared | overridden | blocked. A blocked check means no dispense row was ever written.';
COMMENT ON COLUMN "safety_checks"."override_reason" IS 'Why the pharmacist proceeded anyway. Required by policy whenever outcome is overridden, and the field a coroner reads first.';
COMMENT ON COLUMN "safety_checks"."checked_by_id" IS 'Pharmacist who resolved the warning.';
COMMENT ON COLUMN "safety_checks"."checked_at" IS 'When the check ran.';

CREATE INDEX "idx_checks_dispense_type"
ON "safety_checks" ("dispense_id", "check_type");
CREATE INDEX "idx_checks_outcome_time"
ON "safety_checks" ("outcome", "checked_at");

CREATE TABLE IF NOT EXISTS "insurance_claims" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The fill being billed. One claim per fill is the unit the payer adjudicates.
	"dispense_id" BIGINT NOT NULL,
	-- Insurer or PBM as routed to.
	"payer_name" VARCHAR(160) NOT NULL,
	-- Bank identification number that routes the claim to the right processor.
	"bin_number" VARCHAR(12),
	-- PCN, which narrows routing within the processor.
	"processor_control_number" VARCHAR(24),
	-- Employer group identifier from the card.
	"group_number" VARCHAR(60),
	-- Membership identifier submitted.
	"member_number" VARCHAR(60) NOT NULL,
	-- Submission time. Claims are adjudicated in seconds at the counter, so this is effectively the sale time.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- submitted | paid | rejected | reversed. A reversal is its own state because returned stock has to unwind the money too.
	"status" VARCHAR(24) NOT NULL DEFAULT 'submitted',
	-- Amount claimed in minor units.
	"billed_cents" INTEGER NOT NULL,
	-- Amount the payer allowed. Null until adjudicated.
	"paid_cents" INTEGER,
	-- Copay left with the patient, which must reconcile with the dispense price.
	"patient_pay_cents" INTEGER,
	-- ISO 4217 currency for all amounts on the row.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Payer reject code, e.g. 79 for refill too soon. The code, not the message, is what staff act on.
	"rejection_code" VARCHAR(16),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "insurance_claims" IS 'The money side of a fill. Tied to the dispense rather than the prescription because a payer adjudicates each fill separately, and a reversal has to name the exact fill it undoes.';
COMMENT ON COLUMN "insurance_claims"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "insurance_claims"."dispense_id" IS 'The fill being billed. One claim per fill is the unit the payer adjudicates.';
COMMENT ON COLUMN "insurance_claims"."payer_name" IS 'Insurer or PBM as routed to.';
COMMENT ON COLUMN "insurance_claims"."bin_number" IS 'Bank identification number that routes the claim to the right processor.';
COMMENT ON COLUMN "insurance_claims"."processor_control_number" IS 'PCN, which narrows routing within the processor.';
COMMENT ON COLUMN "insurance_claims"."group_number" IS 'Employer group identifier from the card.';
COMMENT ON COLUMN "insurance_claims"."member_number" IS 'Membership identifier submitted.';
COMMENT ON COLUMN "insurance_claims"."submitted_at" IS 'Submission time. Claims are adjudicated in seconds at the counter, so this is effectively the sale time.';
COMMENT ON COLUMN "insurance_claims"."status" IS 'submitted | paid | rejected | reversed. A reversal is its own state because returned stock has to unwind the money too.';
COMMENT ON COLUMN "insurance_claims"."billed_cents" IS 'Amount claimed in minor units.';
COMMENT ON COLUMN "insurance_claims"."paid_cents" IS 'Amount the payer allowed. Null until adjudicated.';
COMMENT ON COLUMN "insurance_claims"."patient_pay_cents" IS 'Copay left with the patient, which must reconcile with the dispense price.';
COMMENT ON COLUMN "insurance_claims"."currency_code" IS 'ISO 4217 currency for all amounts on the row.';
COMMENT ON COLUMN "insurance_claims"."rejection_code" IS 'Payer reject code, e.g. 79 for refill too soon. The code, not the message, is what staff act on.';

CREATE INDEX "idx_claims_dispense"
ON "insurance_claims" ("dispense_id");
CREATE INDEX "idx_claims_status_time"
ON "insurance_claims" ("status", "submitted_at");

CREATE TABLE IF NOT EXISTS "counselling_records" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Fill the counselling relates to.
	"dispense_id" BIGINT NOT NULL,
	-- Who counselled. Only a pharmacist may.
	"pharmacist_id" BIGINT NOT NULL,
	-- Whether counselling was offered at all. In several jurisdictions the offer itself is the legal requirement.
	"was_offered" BOOLEAN NOT NULL DEFAULT true,
	-- Whether the patient took it up. A declined offer is a valid, recordable outcome.
	"was_accepted" BOOLEAN NOT NULL DEFAULT false,
	-- in_person | phone | video | written.
	"method" VARCHAR(20) NOT NULL DEFAULT 'in_person',
	-- What was covered, e.g. inhaler technique, drowsiness, alcohol.
	"topics" VARCHAR(255),
	-- When it happened.
	"counselled_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "counselling_records" IS 'Proof that the conversation happened, per fill. Unique on dispense so the record cannot be padded, and separate from the dispense row because the offer can be declined without invalidating the sale.';
COMMENT ON COLUMN "counselling_records"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "counselling_records"."dispense_id" IS 'Fill the counselling relates to.';
COMMENT ON COLUMN "counselling_records"."pharmacist_id" IS 'Who counselled. Only a pharmacist may.';
COMMENT ON COLUMN "counselling_records"."was_offered" IS 'Whether counselling was offered at all. In several jurisdictions the offer itself is the legal requirement.';
COMMENT ON COLUMN "counselling_records"."was_accepted" IS 'Whether the patient took it up. A declined offer is a valid, recordable outcome.';
COMMENT ON COLUMN "counselling_records"."method" IS 'in_person | phone | video | written.';
COMMENT ON COLUMN "counselling_records"."topics" IS 'What was covered, e.g. inhaler technique, drowsiness, alcohol.';
COMMENT ON COLUMN "counselling_records"."counselled_at" IS 'When it happened.';

CREATE UNIQUE INDEX "uq_counselling_dispense"
ON "counselling_records" ("dispense_id");

CREATE TABLE IF NOT EXISTS "controlled_register" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The dispense being registered. Unique, because a controlled supply appears in the register exactly once.
	"dispense_id" BIGINT NOT NULL UNIQUE,
	-- Product supplied, repeated here so the register stands alone if the catalogue is reorganised.
	"drug_id" BIGINT NOT NULL,
	-- Schedule at the time of supply, snapshotted because rescheduling happens and the register records the law as it then was.
	"controlled_schedule" VARCHAR(8) NOT NULL,
	-- Units supplied.
	"quantity" INTEGER NOT NULL,
	-- Stock remaining for that drug after this entry. The register is a ledger: the balance is written down, not recomputed, so a discrepancy is visible at the line that caused it.
	"running_balance" INTEGER NOT NULL,
	-- What identity document was shown, recorded where the jurisdiction requires it.
	"patient_identification" VARCHAR(160),
	-- Name of the person collecting when it is not the patient.
	"collected_by" VARCHAR(160),
	-- Pharmacist making the entry.
	"pharmacist_id" BIGINT NOT NULL,
	-- Second signature, required for destructions and for some schedules.
	"witness_id" BIGINT,
	-- Entry time. Entries are append-only and are never edited.
	"recorded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "controlled_register" IS 'The statutory controlled-drugs register: append-only, sequential, and carrying its own running balance. It is a separate table from dispenses because it outlives them in retention terms and must never be touched by ordinary application updates.';
COMMENT ON COLUMN "controlled_register"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "controlled_register"."dispense_id" IS 'The dispense being registered. Unique, because a controlled supply appears in the register exactly once.';
COMMENT ON COLUMN "controlled_register"."drug_id" IS 'Product supplied, repeated here so the register stands alone if the catalogue is reorganised.';
COMMENT ON COLUMN "controlled_register"."controlled_schedule" IS 'Schedule at the time of supply, snapshotted because rescheduling happens and the register records the law as it then was.';
COMMENT ON COLUMN "controlled_register"."quantity" IS 'Units supplied.';
COMMENT ON COLUMN "controlled_register"."running_balance" IS 'Stock remaining for that drug after this entry. The register is a ledger: the balance is written down, not recomputed, so a discrepancy is visible at the line that caused it.';
COMMENT ON COLUMN "controlled_register"."patient_identification" IS 'What identity document was shown, recorded where the jurisdiction requires it.';
COMMENT ON COLUMN "controlled_register"."collected_by" IS 'Name of the person collecting when it is not the patient.';
COMMENT ON COLUMN "controlled_register"."pharmacist_id" IS 'Pharmacist making the entry.';
COMMENT ON COLUMN "controlled_register"."witness_id" IS 'Second signature, required for destructions and for some schedules.';
COMMENT ON COLUMN "controlled_register"."recorded_at" IS 'Entry time. Entries are append-only and are never edited.';

CREATE INDEX "idx_register_drug_time"
ON "controlled_register" ("drug_id", "recorded_at");

